const vars = ['--ult-color-accent', '--ult-color-surface', '--ult-color-text', '--ult-color-border-focus'];
async function computed(page, sel) {
  return page.evaluate(([sel, vars]) => {
    const el = document.querySelector(sel); if (!el) return null;
    const cs = getComputedStyle(el);
    return { colorScheme: cs.colorScheme, bg: cs.backgroundColor, color: cs.color, ...Object.fromEntries(vars.map(v => [v, cs.getPropertyValue(v).trim()])) };
  }, [sel, vars]);
